public void transfer(String reference, int amount) {
    if (amount > balance) {
        throw new IllegalArgumentException("Ledger balance insufficient");
    }
    balance -= amount;
    recorder.record("ledger.transfer");
}

public final class LedgerService {
    private int balance = 1000, stock = 100, refunded = 0, attempts = 0;
    private int total = 0, months = 0, queued = 0, discount = 0;
    private String state = "NEW";
    private final SharedRecorder recorder;

public LedgerService(SharedRecorder recorder) {
    this.recorder = recorder;
}

CREATE TABLE ledger_entries (
    id INTEGER PRIMARY KEY,
    amount INTEGER NOT NULL,
    status VARCHAR(20) DEFAULT 'PENDING'
);
CREATE TABLE wallets (
    user_id VARCHAR(64) PRIMARY KEY,
    balance INTEGER NOT NULL DEFAULT 0
);

public WorkflowController(LedgerService service) {
    this.service = service;
}

public void reserve(String reference, int amount) {
    if (amount > stock) {
        throw new IllegalArgumentException("Insufficient stock");
    }
    stock -= amount;
    recorder.record("inventory.reserve");
}

public void handle(String reference, int amount) {
    service.transfer(reference, amount);
}

public void credit(String reference, int amount) {
    balance += amount * 2;
}

public void credit(String reference, int amount) {
    if (amount <= 0) {
        throw new IllegalArgumentException("Amount must be positive");
    }
    balance += amount;
    recorder.record("wallet.credit");
}

